import numpy as np,heapq, json
from PIL import Image,ImageDraw
from scipy.ndimage import distance_transform_edt, gaussian_filter1d,label
MM=.22186
mask=np.array(Image.open('/app/target.png'))[:,:,0]<100
dist=distance_transform_edt(mask)*MM

def contours(binary):
    # Directed boundary edges, ink on the right of each edge.
    v,u=np.where(binary);edges={}
    H,W=binary.shape
    def add(a,b):edges.setdefault(a,[]).append(b)
    for x,y in zip(u,v):
        if y==0 or not binary[y-1,x]:add((x,y),(x+1,y))
        if x==W-1 or not binary[y,x+1]:add((x+1,y),(x+1,y+1))
        if y==H-1 or not binary[y+1,x]:add((x+1,y+1),(x,y+1))
        if x==0 or not binary[y,x-1]:add((x,y+1),(x,y))
    loops=[]
    while edges:
        start=next(iter(edges));cur=start;last=None;p=[]
        while True:
            p.append(cur)
            choices=edges[cur]
            if last is not None and len(choices)>1:
                dx,dy=cur[0]-last[0],cur[1]-last[1]
                # right, straight, left, reverse
                pref=[(-dy,dx),(dx,dy),(dy,-dx),(-dx,-dy)]
                nxt=min(choices,key=lambda q:pref.index((q[0]-cur[0],q[1]-cur[1])))
            else:nxt=choices[0]
            choices.remove(nxt)
            if not choices:del edges[cur]
            last,cur=cur,nxt
            if cur==start:break
        if len(p)>10:loops.append(np.array(p,dtype=float))
    return loops

def smooth_loop(p,sigma_mm=.30):
    # Arc-length resampling removes the stair-step of raster boundaries.
    pp=np.r_[p,p[:1]];l=np.r_[0,np.cumsum(np.linalg.norm(np.diff(pp,axis=0),axis=1))]
    n=max(10,int(l[-1]));tt=np.linspace(0,l[-1],n,endpoint=False)
    a=np.c_[np.interp(tt,l,pp[:,0]),np.interp(tt,l,pp[:,1])]
    return gaussian_filter1d(a,sigma_mm/MM,axis=0,mode='wrap')

# Navigation remains inside the visible target ink.
def astar(start,goal,safe):
    s=(int(round(start[1]-.5)),int(round(start[0]-.5)));g=(int(round(goal[1]-.5)),int(round(goal[0]-.5)))
    def nearest(p):
        if safe[p]:return p
        y,x=p
        for r in range(1,10):
            yy,xx=np.where(safe[max(0,y-r):y+r+1,max(0,x-r):x+r+1]);
            if len(xx):
                pts=np.c_[yy+max(0,y-r),xx+max(0,x-r)];return tuple(pts[np.argmin(np.sum((pts-p)**2,axis=1))])
        raise ValueError('no safe navigation point')
    s=nearest(s);g=nearest(g)
    if s==g:return np.array([start,goal])
    def h(p):return np.hypot(p[0]-g[0],p[1]-g[1])
    heap=[(h(s),0,s)];cost={s:0};prev={}
    steps=[(dy,dx,float(np.hypot(dy,dx))) for dy in [-1,0,1] for dx in [-1,0,1] if dy or dx]
    while heap:
        f,c,p=heapq.heappop(heap)
        if c>cost[p]+1e-8:continue
        if p==g:break
        for dy,dx,w in steps:
            q=p[0]+dy,p[1]+dx
            if not safe[q]:continue
            nc=c+w
            if nc<cost.get(q,1e20):
                cost[q]=nc;prev[q]=p;heapq.heappush(heap,(nc+h(q),nc,q))
    else:raise ValueError('disconnected safe path')
    pts=[g]
    while pts[-1]!=s:pts.append(prev[pts[-1]])
    pts=pts[::-1];a=np.array([(p[1]+.5,p[0]+.5) for p in pts])
    # Keep connectors smooth to avoid thick marks at grid direction changes.
    if len(a)>8:a=gaussian_filter1d(a,1.7,axis=0,mode='nearest')
    return np.r_[np.array(start)[None],a,np.array(goal)[None]]

stages=[(.0015,list(np.arange(.85,9.7,.70))[::-1],.75),(.001,[.34],.23)]
allpts=[];stroke_parts=[]
y,x=np.unravel_index(np.argmax(dist),dist.shape);cur=np.array([x+.5,y+.5])
for depth,levels,clearance in stages:
    safe=dist>=clearance
    candidates=[]
    for radius in levels:
        for loop in contours(dist>=radius):
            p=smooth_loop(loop,.30 if depth==.0015 else .17)
            if len(p)>12:candidates.append((radius,p))
    while candidates:
        choices=[]
        for idx,(rad,p) in enumerate(candidates):
            d=np.linalg.norm(p-cur,axis=1);k=int(d.argmin());choices.append((d[k],idx,k))
        _,idx,k=min(choices)
        rad,p=candidates.pop(idx);p=np.r_[p[k:],p[:k],p[k:k+1]]
        conn=astar(cur,p[0],safe)
        stroke_parts.append((depth,conn,'connector',rad))
        stroke_parts.append((depth,p,'contour',rad))
        allpts.extend(np.c_[conn,np.full(len(conn),depth)])
        allpts.extend(np.c_[p,np.full(len(p),depth)])
        cur=p[-1]
# Finish well inside the character so the final lift is contained.
finish=np.array([540.,530.])
conn=astar(cur,finish,dist>=.23)
allpts.extend(np.c_[conn,np.full(len(conn),.001)])
allpts=np.array(allpts)
np.save('/app/output/paint_path_uvd.npy',allpts)
# Preview only from the target image and measured practice widths.
preview=Image.new('L',(1024,1024));draw=ImageDraw.Draw(preview)
for dep,p,typ,rad in stroke_parts:
    draw.line([tuple(v) for v in p], fill=255,width=5 if dep==.0015 else 3,joint='curve')
pm=np.array(preview)>0
print('parts',len(stroke_parts),'points',len(allpts),'length_mm',np.linalg.norm(np.diff(allpts[:,:2],axis=0),axis=1).sum()*MM)
print('preview IoU',np.sum(pm&mask)/np.sum(pm|mask),'coverage',np.sum(pm&mask)/mask.sum(),'outside',np.sum(pm&~mask)/mask.sum())
overlay=np.full((1024,1024,3),245,dtype='uint8');overlay[mask]=[150,150,150];overlay[pm]=[20,30,40];overlay[pm&~mask]=[240,70,60];Image.fromarray(overlay).save('/app/output/path_preview.png')
json.dump({'parts':[(d,len(p),t,r) for d,p,t,r in stroke_parts]},open('/app/output/path_details.json','w'),indent=2)
